def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        for data in iter(lambda:stream.read(1<<20),b''):h.update(data)
    return h.hexdigest()
def write(path,value):
    with path.open('x') as stream:json.dump(value,stream,sort_keys=True,indent=2,allow_nan=False);stream.write('\n')
def main():
    before=json.loads((OWN/'source_hashes_before.json').read_text());after={p:{'expected_sha256':v['expected_sha256'],'actual_sha256':digest(ROOT/p),'bytes':(ROOT/p).stat().st_size} for p,v in before.items()}
