    write(OWN/'owned_artifact_manifest.json',{'created_at_utc':datetime.now(timezone.utc).isoformat(),'scope':'All pre-seal own files, solely source/review/handmade fixtures; no actual project arrays.','total_bytes':sum(v['bytes'] for v in artifacts.values()),'files':artifacts})
