    receipt={'schema':'census_native_qualification_runner_v1_independent_receipt','created_at_utc':datetime.now(timezone.utc).isoformat(),'project_root':str(ROOT),'hypothesis_id':'H021','status':'qualified_source_handmade_CPU_only','actual_admission':False,'fixture_mode':False,'verdict_scope':'Exact frozen shipped source/config qualified for observation-only byte/lineage preparation and independently frozen target-free qualification under root-owned actual manifest/resource/phase admission. No blocking source or handmade numerical defect found. Actual32, fitting, predictive benefit and resource performance remain unrun.','independence':{'fresh_review_assignment':True,'desired_verdict_supplied':False,'own_native_recipe':True,'author_immutable_suite_rerun':True,'author_fixture_envelope_reused_with_new_native_recipe':True,'author_sources_or_artifacts_modified':False},'artifact_sha256':compact,'dependency_sha256':config['source_sha256'],'all_25_config_dependencies_verified_unchanged':True,'project_runner_import_closure_all_13_modules_pinned':True,'source_before_after_equal':True,'results':{'source_suite':{'passed':21,'seconds':23.46,'wrapper_seconds':source['wall_seconds'],'returncode':0},'independent_attempt01':{'passed':35,'seconds':51.79,'returncode':0},'independent_final':{'passed':36,'seconds':57.51,'wrapper_seconds':final['wall_seconds'],'returncode':0},'preserved_failed_tests':0,'exact_default_config_fixture_review_guard':guard,'own_fixture_structural_phase':ownmetrics,'small_model_real_numerics':numerical_metrics(small),'shipped_two_layer_model_real_numerics':numerical_metrics(shipped),'default_initial_state_sha256_by_dtype':json.loads((OWN/'default_initial_state_sha256_by_dtype.json').read_text())},'qualified_contracts':['Complete exact source pins and global observed byte closure before any native/NPZ/Torch array decoder; changed late-parent bytes fail before decoder sentinels.','Exact original ordered source/derived roster, native direct float64 sample dates, subject/haplotype actual-mode pairing, frozen prepared sample/readout/target slots and physical grid/tree/landmark metadata.','Original source reference x48 transformation, exact F47 columns0-6 and8-47, original TRAIN lineage and identity_no_fitted_scaler; no biological labels in inputs.','Complete native sample-ancestor union, unused node exclusion, anonymous unary suppression only after full producer parity, native donor/census/group/right-hold checks.','Inspection digests are evidence only; independently hashed complete32 freeze and expected certificate map required before numerical rebuild/forward.','Metadata-only TRAIN minimum/maximum original-tree counts first; all32 fixed cells and both dtype/allfive controls required.','Same seeded state each dtype/control; separate/forest outputs/VJPs, float32/float64 parity, layer mass/source bounds, float64 directional derivatives and synthetic clipped disposable AdamW qualify handmade inputs.'],'concerns':concerns,'external_root_duties':rootbounds['root_duties'],'blocked_unrun_gates':['Actual original observed/native/prepared/scaler/role/target-column join and source file byte admission.','Actual32 structural/collision/support-opportunity inspection and independently frozen certificate evidence.','Actual TRAIN minimum/maximum then fixed full32 real numerical checks and all dtype/control coverage.','Actual resource/runtime/launcher/storage/phase admission, any fitted protocol, predictive/scientific/speed/memory claim.'],'actions':{'SSH_alias':'anogena','read_AGENTS_first':True,'writes_only_owned_review_directory':True,'main_project_Python':True,'one_CPU_thread':True,'CUDA_VISIBLE_DEVICES':'','PYTHONDONTWRITEBYTECODE':'1','handmade_native_Tables_only':True,'handmade_forward_VJP_directional_disposable_steps':True,'installed_runtime_code_hashing_only':True,'actual_observation_model_target_bank_access':False,'live_runtime_ledger_device_state_access':False,'native_inference_or_stochastic_simulation':False,'fitting':False,'GPU_or_controller':False,'installation':False,'Git':False,'source_author_or_configuration_edit':False,'ledger_decision_or_actual_admission_creation':False,'bulk_project_storage_scan':False,'Mac_project_file_writes':False},'owned_directory_only':str(OWN)}
    receiptpath=OWN/'receipt.json';write(receiptpath,receipt)
    binding={'schema':'census_native_qualification_review_binding_v1','status':'qualified_source_handmade_CPU_only','runner_source_sha256':after['src/arggnn/census_native_qualification_runner_v1.py']['actual_sha256'],'runner_config_sha256':after['configs/census_native_qualification_runner_v1.json']['actual_sha256'],'actual_admission':False,'review_receipt_ref':{'path':str(receiptpath.relative_to(ROOT)),'sha256':digest(receiptpath)}}
    tree=ast.parse((ROOT/'src/arggnn/census_native_qualification_runner_v1.py').read_text());keys=None
    for node in ast.walk(tree):
        if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='expected_review' for t in node.targets):keys={k.value for k in node.value.keys}
