    print(json.dumps({'status':receipt['status'],'receipt':{'path':str(receiptpath.relative_to(ROOT)),'sha256':digest(receiptpath)},'runner_review':{'path':str((OWN/'runner_review.json').relative_to(ROOT)),'sha256':digest(OWN/'runner_review.json')},'owned_preseal_bytes':sum(v['bytes'] for v in artifacts.values()),'small_model':numerical_metrics(small),'shipped_model':numerical_metrics(shipped)},indent=2))
